"""Only formats frozen multi-station hierarchy results."""
import json
from .pipeline import ROOT
from .research_report_text import markdown


def main():
    r=json.loads((ROOT/'docs/REGIONAL_HIERARCHY_SUMMARY.json').read_text(encoding='utf-8'));s=r['selection'];name=s['diagnostic'];fmt=lambda x:'—' if x is None else f'{x:.3f}'
    lines=['# Общая погодная модель с отдельными поправками станций','',
           '**Выбран прежний минимум.** Иерархический кандидат немного улучшил ранее просмотренные контроли, но не прошёл условия выбора2023–2024 и на отложенных станциях уступил GFS по ложным пересечениям нуля. На него не переключаем продукт; исходный детектор и полевая выдача сохранены.','',
           '## Почему проверен второй подход','',
           'В [первом эксперименте расширения](REGIONAL_MINIMUM_REPORT.md) простое объединение станций ухудшило перенос на исходную станцию. До открытия отложенных целей и2025–2026 зарегистрирован отдельный follow-up: общие15 погодных признаков плюс регуляризованные индикаторы станции, затем фиксированное смешивание с прежним минимумом. Таким образом, устойчивые различия между станциями могут учитываться отдельно от зависимости ошибки от прогнозируемой погоды.',
           'Восемь обучающих станций дают1360 полных станция-ночей2022–2023, включая205 холодных,60 холодных дат и11 приближённых групп волн. Прежнее обучение —184 ночи,21 холодная дата,5 групп. Это увеличение разнообразия архива, а не205 независимых погодных событий. Отложены SHPAKOVSKOYE и MINERALNYYE VODY. Полнота, происхождение, временные границы и ограничения ISD-Lite описаны в первом отчёте.', '',
           '## Предварительно зафиксированный выбор','',
           '24 варианта: Huber(alpha1)/Ridge(alpha10), масштаб индикатора станции1/4, вес холодных1/2, доля иерархического прогноза0.25/0.5/1. Базовые веса разделяют одну дату между её полными станциями и нормируются к числу обучающих дат. Валидационные фолды2022→2023 и2022–2023→2024; финальный fit2022–2023. Параметры станций выводятся только из обучающих целей.',
           'У новой станции индикаторы равны нулю, личная поправка отсутствует; это только исследовательский общий прогноз. Нулевая поправка не доказывает отсутствие микроклиматической ошибки. Станционные признаки не делают модель пригодной для неизвестного сада.',
           'Проверки те же, что у первого эксперимента, для каждого года отдельно: общая/холодная MAE, пропуски и ложные пересечения исходной станции не хуже прежнего минимума; общая/холодная MAE с равным весом дополнительных станций, пропуски и ложные пересечения не хуже GFS. Ни один новый вариант не прошёл всё. Исходы контролей не меняют этот выбор.',
           f"Диагностический вариант **{name}** выбран по холодной MAE исходной станции до контроля, независимо от допуска в продукт. Он смешивает25% модели с отдельными поправками и75% прежнего прогноза.",'',
           '| Год выбора | Вариант | MAE, °C | Холодная MAE, °C | Пропусков | Ложных пересечений |','|---|---|---:|---:|---:|---:|']
    for f in s['fold_scores']:
        for n in ['legacy',name]:
            a=f['groups']['primary'][n];lines.append(f"|{f['year']}|{n}|{fmt(a['mae_c'])}|{fmt(a['cold_mae_c'])}|{a['misses']}|{a['false_alarms']}|")
    failures=[k for k,v in s['gates'][name].items() if not v];lines += ['', 'Кандидат не прошёл: '+', '.join(failures)+'.', '',
              'Это40 вариантов суммарно в двух последовательных prior-экспериментах.2023–2024 многократно использовались при разработке, поэтому даже успешный выбор потребовал бы независимой будущей проверки.','',
              '## Отложенные станции2024','',
              '| Вариант | MAE, °C | Холодная MAE, °C | Пропусков | Ложных пересечений |','|---|---:|---:|---:|---:|']
    for n in ['gfs','legacy','diagnostic']:
        a=r['spatial_2024']['scores'][n];lines.append(f"|{n}|{fmt(a['mae_c'])}|{fmt(a['cold_mae_c'])}|{a['misses']}|{a['false_alarms']}|")
    lines += ['', 'Полные результаты каждой станции сохранены в JSON. Кандидат лучше GFS по ошибке холодных и пропускам, но хуже по общей MAE и ложным пересечениям. Даты связаны с региональной валидацией; это проверка новых сайтов, не независимых погодных событий.', '',
              '## Контроли2025–2026 после фиксации','',
              '| Год | Вариант | MAE, °C | Холодная MAE, °C | Пропусков | Ложных пересечений |','|---|---|---:|---:|---:|---:|']
    for year,z in r['seasons'].items():
        for n in ['gfs','legacy','diagnostic']:
            a=z['scores'][n];lines.append(f"|{year}|{n}|{fmt(a['mae_c'])}|{fmt(a['cold_mae_c'])}|{a['misses']}|{a['false_alarms']}|")
    lines += ['', 'Контроли ранее просмотрены, не новый слепой тест. Кандидат не настраивался по ним и после улучшения не становится выбранным. Сравнение по общим календарным неделям описательное: временная зависимость может выходить за границы блоков.','',
              '**Пересечения нуля минимумом — не тревоги детектора.** Для исходного детектора сохранены все184 объекта, маски и времена; обнаружение6/6 и4/4, ложные тревоги3/1. Этот детектор не переобучается и не переносится на новые станции без отдельной проверки.','',
              '## Решение и следующая проверка','',
              'Работающий продукт сохраняет прежние модели. Иерархический вариант полезен как исследовательская гипотеза: он учитывает неоднородность станций и даёт небольшой контрольный выигрыш, но пока не удовлетворяет политике качества. Более низкая отдельная ошибка не компенсирует ухудшение других показателей и не разрешает менять выбор по2025–2026.',
              'Следующий протокол стоит направить на переносимость между климатическими и высотными режимами и на новые независимые холодные события. Площадка с локальными датчиками необходима для оценки ошибки в саду. Просмотренные отложенные сайты нельзя повторно объявлять новым слепым тестом; эффекты защиты, повреждения и экономика здесь не установлены.','',
              '## Воспроизведение и сохранность','',
              '```powershell','.venv\\Scripts\\python.exe -m agro_checker.regional_hierarchy --select-only','.venv\\Scripts\\python.exe -m agro_checker.regional_hierarchy',
              '.venv\\Scripts\\python.exe -m agro_checker.regional_hierarchy_report','```','',
              'После контроля scientific-модули обоих экспериментов, конфиги, данные и модели заморожены. Повторный выбор проверяет SHA и не переобучает; дорабатываются только отчёты и интерфейс.',
              f"Фиксация UTC{s['selection_saved_at_utc']}; SHA `{r['selection_sha256']}`.",'',
              '[Метрики и происхождение](REGIONAL_HIERARCHY_SUMMARY.json). [Первый эксперимент и архив](REGIONAL_MINIMUM_REPORT.md).']
    lines += ['', 'Проверено 360 Python-тестов и 20 JavaScript-тестов. Они включают запрет будущих/отложенных целей, отсутствие фактов при инференсе, веса зависимых записей, неизменность выбора и детектора. [График сравнения](assets/regional-hierarchy-quality.png).']
    (ROOT/'docs/REGIONAL_HIERARCHY_REPORT.md').write_text(markdown(lines),encoding='utf-8')
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10});fig,axes=plt.subplots(1,3,figsize=(13,4.6),layout='constrained');colors=['#25644c','#c27435']
    for ax,title,groups in [(axes[0],'Исходная станция\nконтрольная общая MAE',[r['seasons'][str(y)]['scores'] for y in [2025,2026]]),
                            (axes[1],'Исходная станция\nконтрольная холодная MAE',[r['seasons'][str(y)]['scores'] for y in [2025,2026]])]:
        key='mae_c' if ax is axes[0] else 'cold_mae_c'
        for j,(n,color) in enumerate(zip(['legacy','diagnostic'],colors)):
            values=[g[n][key] for g in groups];bars=ax.bar([i+(j-.5)*.32 for i in [0,1]],values,.32,color=color,label='Прежняя' if j==0 else 'Кандидат');ax.bar_label(bars,fmt='%.3f',padding=3)
        ax.set_xticks([0,1],['2025','2026']);ax.set_ylabel('Ошибка, °C');ax.set_title(title);ax.set_ylim(0,max(g[n][key] for g in groups for n in ['legacy','diagnostic'])*1.35);ax.spines[['top','right']].set_visible(False);ax.legend(fontsize=9)
    ax=axes[2];values=[r['spatial_2024']['scores'][n]['false_alarms'] for n in ['gfs','legacy','diagnostic']];bars=ax.bar(range(3),values,color=['#607d8b',*colors]);ax.bar_label(bars,padding=3);ax.set_xticks(range(3),['GFS','Прежняя','Кандидат']);ax.set_title('Отложенные станции 2024\nложные пересечения нуля');ax.set_ylabel('Число ночей');ax.set_ylim(0,max(values)*1.25);ax.spines[['top','right']].set_visible(False)
    fig.suptitle('Иерархический кандидат: выигрыш на контролях не разрешает внедрение',fontsize=14);fig.savefig(ROOT/'docs/assets/regional-hierarchy-quality.png',dpi=150);plt.close(fig)
    print('Hierarchy report and research plot saved.')


if __name__=='__main__':main()
